part of 'user_screens.dart';

class ShelfAgingScreen extends StatelessWidget { const ShelfAgingScreen(this.state, {super.key}); final UserState state;
  @override Widget build(BuildContext context) { final today = DateTime.now(); return UserShell(state: state, title: 'Shelf Stock — 3+ Months', showBack: true, child: state.products.isEmpty ? const EmptyMessage('No shelf stock records found.') : ListView.builder(padding: const EdgeInsets.all(12), itemCount: state.products.length, itemBuilder: (_, i) { final p = state.products[i]; final added = DateTime.tryParse('${p['shelf_added_date']}'); final age = added == null ? null : today.difference(added).inDays; final status = age == null ? 'Review' : age >= 90 ? 'Slow Moving' : 'Normal'; return UserCard(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Row(children: [Expanded(child: Text('${p['name']}', style: const TextStyle(fontWeight: FontWeight.w800))), StatusPill(status)]), const SizedBox(height: 8), Text('Shelf quantity: ${number(p['shelf_stock'])}'), Text('Added: ${added == null ? 'Not recorded' : '${added.day}/${added.month}/${added.year}'}  •  Age: ${age == null ? '—' : '$age days'}'), const SizedBox(height: 8), Wrap(spacing: 5, children: ['Move Stock', 'Apply Discount', 'Return Supplier', 'Mark Clearance'].map((a) => OutlinedButton(onPressed: () => _notice(context, '$a requires manager approval.'), child: Text(a, style: const TextStyle(fontSize: 10)))).toList())])); })); }
}

void _notice(BuildContext context, String text) => ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(text)));
